#!/usr/bin/env bash
# Linux counterpart of build_shaders.ps1: every shaders/*.comp to build/shaders/*.spv with glslang, and the PTX
# kernels (VK_NV_cuda_kernel_launch) generated by the Python emitters into build/ptx. Keep the PTX list in step
# with build_shaders.ps1.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
glslang="$root/tools/glslang/bin/glslang"
python="${PYTHON:-python3}"
out="$root/build/shaders"
mkdir -p "$out"
failed=0
for shader in "$root"/shaders/*.comp; do
  name="$(basename "${shader%.comp}")"
  "$glslang" -V --target-env vulkan1.3 -I"$root/shaders" "$shader" -o "$out/$name.spv" || failed=1
done
[ "$failed" = 0 ] || exit 1

ptx="$root/build/ptx"
gen="$root/scripts/ptx"
mkdir -p "$ptx"
emit() { local script="$1"; shift; "$python" "$gen/$script" "$@" > /dev/null; }
for k in 64 128 256; do emit mlp_e4m3.py "$k" "$ptx/mlp_e4m3_K$k.ptx" 3 1 1; done
for c in 64 128 256 512; do emit qkv_e4m3.py "$c" "$ptx/qkv_e4m3_K$c.ptx" 80; done
# GEMM + epilogue variants: residual-seeded E4 (5), residual dual (13), plain E4 (4), plain f16 (8), SiLU E4 (6)
for k in 32 64 128 256 512 1024; do
  for f in 5 13 4 8 6; do emit gemm2_e4m3.py "$k" "$f" "$ptx/gemm2_e4m3_K${k}_f$f.ptx"; done
done
for cfg in "64 4 0" "128 4 0" "256 3 80" "256 4 64"; do
  set -- $cfg
  emit ffn_e4m3.py "$1" "$2" "$ptx/ffn_e4m3_C$1_R$2.ptx" "$3"
  emit ffn_e4m3.py "$1" "$2" "$ptx/ffn_e4m3_C$1_R$2_proj.ptx" "$3" 1
done
for cfg in "4096 1 32 4" "1024 0 16 2" "1024 1 8 4" "1024 0 8 4"; do
  set -- $cfg
  emit gemmt_e4m3.py "$1" "$2" "$3" "$4" "$ptx/gemmt_e4m3_K$1_f$2_p$3_s$4.ptx"
done
for cfg in "4 4" "2 8" "4 8"; do
  set -- $cfg
  emit reduce_e4m3.py "$1" "$2" "$ptx/reduce_e4m3_s$1_f$2.ptx"
done
for cfg in "1024 6 1" "4096 5 4" "1024 8 2" "1024 5 4"; do
  set -- $cfg
  emit gemmv_e4m3.py "$1" "$2" "$3" "$ptx/gemmv_e4m3_K$1_f$2_s$3.ptx"
  # 96-row tiles (two workgroups per SM): 4 A stages x 3 KB + 6 W stages x 4 KB (+ 12 KB residual) = 48 KB
  emit gemmv_e4m3.py "$1" "$2" "$3" "$ptx/gemmv_e4m3_K$1_f$2_s$3_m96.ptx" 4 6 0 0 0 96
done
for padded in 64 128 192 256; do emit global_attention_e4m3.py "$padded" "$ptx/global_attention_e4m3_p$padded.ptx"; done
# any token count (high resolutions): normalize pass + streamed attention
emit global_attention_stream_e4m3.py normalize "$ptx/global_normalize_e4m3.ptx"
emit global_attention_stream_e4m3.py attention "$ptx/global_attention_stream_e4m3.ptx" 4
# split-512 GEMMs through gemmv (96-row tiles, no partition): layer 0 (E4), contract (residual + E4), projection (dual);
# plus the unsplit ViT shapes of high resolutions (many token row groups): contract K4096 f5, qkv K1024 f8, projection K1024 f5
for cfg in "512 4" "512 5" "512 13" "256 5" "4096 5" "1024 8" "1024 5"; do
  set -- $cfg
  emit gemmv_e4m3.py "$1" "$2" 1 "$ptx/gemmv_e4m3_K$1_f$2_s1_m96.ptx" 4 6 0 0 0 96
done
# fused 32-channel block variants: E4 out; E4 + pool; pre + E4 + pool; upres + E4; post + head
for f in 2 66 74 130 48; do emit block32_e4m3.py "$f" "$ptx/block32_e4m3_f$f.ptx"; done
